    decisions: {},          // group_key -> decision row
    decisionsStale: false,  // the READ failed — the map is last-known-good, NOT the truth
    loadedSignedIn: false,
    loading: false, error: null,
    filter: "todo", q: "",
    open: {},               // group_key -> true. Lives HERE, not in the DOM:
